SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT SQL.SQLCODE
DECLARE n NUMBER;
    PROCEDURE empty_result(query_ CLOB, message_ VARCHAR2) IS
    BEGIN
        EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ('||query_||')' INTO n;
        IF n!=0 THEN RAISE_APPLICATION_ERROR(-20020,message_||': '||n); END IF;
    END;
BEGIN
    empty_result(q'~SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.AJMT_TYPE_CD,A.AJMT_RT,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='FLT_PSG' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL MINUS SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,AJMT_TYPE_CD,AJMT_RT,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT_V2~','Missing current rows: TN_PM_SMLT_USER_FLT_PSG_AJMT');
    empty_result(q'~SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,AJMT_TYPE_CD,AJMT_RT,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT_V2 MINUS SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.AJMT_TYPE_CD,A.AJMT_RT,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='FLT_PSG' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL~','Extra current rows: TN_PM_SMLT_USER_FLT_PSG_AJMT');
    empty_result(q'~SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.CHKN_ISL_CD,A.BOOTH_CNT,A.KOS_CNT,A.SBD_CNT,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='CHKN' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL MINUS SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,CHKN_ISL_CD,BOOTH_CNT,KOS_CNT,SBD_CNT,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL_V2~','Missing current rows: TN_PM_SMLT_USER_CHKN_ISL');
    empty_result(q'~SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,CHKN_ISL_CD,BOOTH_CNT,KOS_CNT,SBD_CNT,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL_V2 MINUS SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.CHKN_ISL_CD,A.BOOTH_CNT,A.KOS_CNT,A.SBD_CNT,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='CHKN' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL~','Extra current rows: TN_PM_SMLT_USER_CHKN_ISL');
    empty_result(q'~SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.CHKN_ISL_CD,A.OPER_HR_SN,A.OPER_BGNG_HOUR,A.OPER_END_HOUR,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='CHKN' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL MINUS SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,CHKN_ISL_CD,OPER_HR_SN,OPER_BGNG_HOUR,OPER_END_HOUR,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR_V2~','Missing current rows: TN_PM_SMLT_USER_CHKN_OPER_HR');
    empty_result(q'~SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,CHKN_ISL_CD,OPER_HR_SN,OPER_BGNG_HOUR,OPER_END_HOUR,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR_V2 MINUS SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.CHKN_ISL_CD,A.OPER_HR_SN,A.OPER_BGNG_HOUR,A.OPER_END_HOUR,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='CHKN' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL~','Extra current rows: TN_PM_SMLT_USER_CHKN_OPER_HR');
    empty_result(q'~SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.CHKN_ISL_CD,A.BOOTH_NO,A.ALN_CD,A.CSTM_ALTMNT_YN,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='CHKN' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL MINUS SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,CHKN_ISL_CD,BOOTH_NO,ALN_CD,CSTM_ALTMNT_YN,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH_V2~','Missing current rows: TN_PM_SMLT_USER_CHKN_BOOTH');
    empty_result(q'~SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,CHKN_ISL_CD,BOOTH_NO,ALN_CD,CSTM_ALTMNT_YN,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH_V2 MINUS SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.CHKN_ISL_CD,A.BOOTH_NO,A.ALN_CD,A.CSTM_ALTMNT_YN,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='CHKN' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL~','Extra current rows: TN_PM_SMLT_USER_CHKN_BOOTH');
    empty_result(q'~SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.DPTGT_NO,A.OPER_YN,A.SCSH_CNTOM,A.GNRL_SRCH_CNTOM,A.SMART_PASS_SRCH_CNTOM,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='DEP' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL MINUS SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,DPTGT_NO,OPER_YN,SCSH_CNTOM,GNRL_SRCH_CNTOM,SMART_PASS_SRCH_CNTOM,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_V2~','Missing current rows: TN_PM_SMLT_USER_DPTGT');
    empty_result(q'~SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,DPTGT_NO,OPER_YN,SCSH_CNTOM,GNRL_SRCH_CNTOM,SMART_PASS_SRCH_CNTOM,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_V2 MINUS SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.DPTGT_NO,A.OPER_YN,A.SCSH_CNTOM,A.GNRL_SRCH_CNTOM,A.SMART_PASS_SRCH_CNTOM,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='DEP' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL~','Extra current rows: TN_PM_SMLT_USER_DPTGT');
    empty_result(q'~SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.DPTGT_NO,A.OPER_HR_SN,A.OPER_BGNG_HOUR,A.OPER_END_HOUR,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='DEP' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL MINUS SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,DPTGT_NO,OPER_HR_SN,OPER_BGNG_HOUR,OPER_END_HOUR,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR_V2~','Missing current rows: TN_PM_SMLT_USER_DPTGT_OPER_HR');
    empty_result(q'~SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,DPTGT_NO,OPER_HR_SN,OPER_BGNG_HOUR,OPER_END_HOUR,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR_V2 MINUS SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.DPTGT_NO,A.OPER_HR_SN,A.OPER_BGNG_HOUR,A.OPER_END_HOUR,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='DEP' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL~','Extra current rows: TN_PM_SMLT_USER_DPTGT_OPER_HR');
    empty_result(q'~SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.DPTGT_NO,A.PLAN_SN,A.OPER_BGNG_HOUR,A.OPER_END_HOUR,A.SCSH_CNTOM,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='DEP' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL MINUS SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,DPTGT_NO,PLAN_SN,OPER_BGNG_HOUR,OPER_END_HOUR,SCSH_CNTOM,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN_V2~','Missing current rows: TN_PM_SMLT_SCSH_OPER_PLAN');
    empty_result(q'~SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,DPTGT_NO,PLAN_SN,OPER_BGNG_HOUR,OPER_END_HOUR,SCSH_CNTOM,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN_V2 MINUS SELECT M.OWNER_USER_ID,M.EXCN_YMD,A.TMNL_ID,A.DPTGT_NO,A.PLAN_SN,A.OPER_BGNG_HOUR,A.OPER_END_HOUR,A.SCSH_CNTOM,A.FRST_RGTR_ID,A.FRST_RGTR_IP_ADDR,A.FRST_REG_DT,A.LAST_MDFR_ID,A.LAST_MDFR_IP_ADDR,A.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN_LGC A JOIN PMOWN.TN_PM_SMLT_LEGACY_COND_MAP M ON A.SMLT_ID=M.OLD_SMLT_ID AND A.TMNL_ID=M.TMNL_ID AND M.AREA_CD='DEP' WHERE M.SELECTED_YN='Y' AND M.REASON IS NULL~','Extra current rows: TN_PM_SMLT_SCSH_OPER_PLAN');
    empty_result(q'~SELECT * FROM PMOWN.TN_PM_SMLT_LEGACY_ISSUE WHERE RESOLUTION IS NULL~','Unresolved legacy issues');
    empty_result(q'~SELECT * FROM PMOWN.TN_PM_SMLT_LEGACY_EXEC_MAP WHERE NEW_SMLT_ID IS NULL OR REASON IS NOT NULL~','Unmapped requests');
    empty_result(q'~SELECT U.SMLT_REQ_ID FROM PMOWN.TN_PM_SMLT_USER_MSTR_LGC U WHERE NOT EXISTS (SELECT 1 FROM PMOWN.TN_PM_SMLT_USER_MSTR_V2 V WHERE V.SMLT_REQ_ID=U.SMLT_REQ_ID)~','Missing requests');
    empty_result(q'~SELECT M.SMLT_ID FROM PMOWN.TN_PM_SMLT_MSTR M WHERE M.SMLT_TYPE='WhatIf' AND (SELECT COUNT(*) FROM PMOWN.TN_PM_SMLT_COND_SNAPSHOT C WHERE C.SMLT_ID=M.SMLT_ID)!=6~','Missing frozen conditions');
    empty_result(q'~SELECT R.SMLT_ID FROM PMOWN.TN_PM_SMLT_RSLT_DTL R WHERE NOT EXISTS (SELECT 1 FROM PMOWN.TN_PM_SMLT_MSTR M WHERE M.SMLT_ID=R.SMLT_ID)~','Orphan results');
    empty_result(q'~SELECT R.SMLT_ID FROM PMOWN.TN_PM_SMLT_RSLT_DTL_REG_EXCL R WHERE NOT EXISTS (SELECT 1 FROM PMOWN.TN_PM_SMLT_MSTR M WHERE M.SMLT_ID=R.SMLT_ID)~','Orphan excluded results');
    empty_result(q'~SELECT A.SMLT_ID FROM PMOWN.TN_PM_SMLT_USER_MSTR_V2 A JOIN PMOWN.TN_PM_SMLT_MSTR M ON M.SMLT_ID=A.SMLT_ID WHERE A.EXCN_YMD!=M.EXCN_YMD OR (A.RSLT_SMLT_ID IS NOT NULL AND A.RSLT_SMLT_ID!=A.SMLT_ID)~','Inconsistent master links');
    empty_result(q'~SELECT U.SMLT_REQ_ID,M.NEW_SMLT_ID,X.EXCN_YMD,CASE WHEN U.RSLT_SMLT_ID IS NOT NULL THEN M.NEW_SMLT_ID END,U.MDL_RSRC_ID,U.FLT_SCHDL_RSRC_ID,U.CKNCT_ALCTN_RSRC_ID,U.SBD_CNTRL_ALCTN_ID,U.PRPT_STNG_RSRC_ID,U.FCLTY_OPNG_DPTCNY_SRNG_RSRC_ID,U.FCLTY_OPNG_DPTCNY_RSRC_ID,U.FCLTY_OPNG_ENTCNY_RSRC_ID,U.FCLTY_OPNG_SCRTY_CNTRL_RSRC_ID,U.FCLTY_OPNG_TR_SCRTY_CNTRL_RSRC_ID,U.CKNCT_SRVC_HR_RSRC_ID,U.CKNCT_TYPE_CNTRL_RSRC_ID,U.CHKN_TYPE_RSRC_ID,U.RPT_STNG_ATRB_ID,U.SMLT_RSLT_SFX,U.SMLT_STTS,U.QUEUE_DT,U.EXCT_DT,U.END_DT,U.ERR_MSG,U.FRST_RGTR_ID,U.FRST_RGTR_IP_ADDR,U.FRST_REG_DT,U.LAST_MDFR_ID,U.LAST_MDFR_IP_ADDR,U.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_MSTR_LGC U JOIN PMOWN.TN_PM_SMLT_LEGACY_EXEC_MAP M ON M.OLD_REQ_ID=U.SMLT_REQ_ID JOIN PMOWN.TN_PM_SMLT_MSTR X ON X.SMLT_ID=M.NEW_SMLT_ID WHERE M.REASON IS NULL AND M.NEW_SMLT_ID IS NOT NULL MINUS SELECT SMLT_REQ_ID,SMLT_ID,EXCN_YMD,RSLT_SMLT_ID,MDL_RSRC_ID,FLT_SCHDL_RSRC_ID,CKNCT_ALCTN_RSRC_ID,SBD_CNTRL_ALCTN_ID,PRPT_STNG_RSRC_ID,FCLTY_OPNG_DPTCNY_SRNG_RSRC_ID,FCLTY_OPNG_DPTCNY_RSRC_ID,FCLTY_OPNG_ENTCNY_RSRC_ID,FCLTY_OPNG_SCRTY_CNTRL_RSRC_ID,FCLTY_OPNG_TR_SCRTY_CNTRL_RSRC_ID,CKNCT_SRVC_HR_RSRC_ID,CKNCT_TYPE_CNTRL_RSRC_ID,CHKN_TYPE_RSRC_ID,RPT_STNG_ATRB_ID,SMLT_RSLT_SFX,SMLT_STTS,QUEUE_DT,EXCT_DT,END_DT,ERR_MSG,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_MSTR_V2~','Changed request columns');
    empty_result(q'~SELECT SMLT_REQ_ID,SMLT_ID,EXCN_YMD,RSLT_SMLT_ID,MDL_RSRC_ID,FLT_SCHDL_RSRC_ID,CKNCT_ALCTN_RSRC_ID,SBD_CNTRL_ALCTN_ID,PRPT_STNG_RSRC_ID,FCLTY_OPNG_DPTCNY_SRNG_RSRC_ID,FCLTY_OPNG_DPTCNY_RSRC_ID,FCLTY_OPNG_ENTCNY_RSRC_ID,FCLTY_OPNG_SCRTY_CNTRL_RSRC_ID,FCLTY_OPNG_TR_SCRTY_CNTRL_RSRC_ID,CKNCT_SRVC_HR_RSRC_ID,CKNCT_TYPE_CNTRL_RSRC_ID,CHKN_TYPE_RSRC_ID,RPT_STNG_ATRB_ID,SMLT_RSLT_SFX,SMLT_STTS,QUEUE_DT,EXCT_DT,END_DT,ERR_MSG,FRST_RGTR_ID,FRST_RGTR_IP_ADDR,FRST_REG_DT,LAST_MDFR_ID,LAST_MDFR_IP_ADDR,LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_MSTR_V2 MINUS SELECT U.SMLT_REQ_ID,M.NEW_SMLT_ID,X.EXCN_YMD,CASE WHEN U.RSLT_SMLT_ID IS NOT NULL THEN M.NEW_SMLT_ID END,U.MDL_RSRC_ID,U.FLT_SCHDL_RSRC_ID,U.CKNCT_ALCTN_RSRC_ID,U.SBD_CNTRL_ALCTN_ID,U.PRPT_STNG_RSRC_ID,U.FCLTY_OPNG_DPTCNY_SRNG_RSRC_ID,U.FCLTY_OPNG_DPTCNY_RSRC_ID,U.FCLTY_OPNG_ENTCNY_RSRC_ID,U.FCLTY_OPNG_SCRTY_CNTRL_RSRC_ID,U.FCLTY_OPNG_TR_SCRTY_CNTRL_RSRC_ID,U.CKNCT_SRVC_HR_RSRC_ID,U.CKNCT_TYPE_CNTRL_RSRC_ID,U.CHKN_TYPE_RSRC_ID,U.RPT_STNG_ATRB_ID,U.SMLT_RSLT_SFX,U.SMLT_STTS,U.QUEUE_DT,U.EXCT_DT,U.END_DT,U.ERR_MSG,U.FRST_RGTR_ID,U.FRST_RGTR_IP_ADDR,U.FRST_REG_DT,U.LAST_MDFR_ID,U.LAST_MDFR_IP_ADDR,U.LAST_MDFCN_DT FROM PMOWN.TN_PM_SMLT_USER_MSTR_LGC U JOIN PMOWN.TN_PM_SMLT_LEGACY_EXEC_MAP M ON M.OLD_REQ_ID=U.SMLT_REQ_ID JOIN PMOWN.TN_PM_SMLT_MSTR X ON X.SMLT_ID=M.NEW_SMLT_ID WHERE M.REASON IS NULL AND M.NEW_SMLT_ID IS NOT NULL~','Unexpected request columns');
    DBMS_OUTPUT.PUT_LINE('Relational checks passed. Verify archived inputs, source backups and CAST contract separately.');
END;
/
SELECT COUNT(*) RESULT_ROWS,SUM(WTNG_PSG_CNT) WAIT_SUM,SUM(TRNST_PSG_CNT) PROCESSED_SUM FROM PMOWN.TN_PM_SMLT_RSLT_DTL;
SELECT COUNT(*) EXCLUDED_ROWS FROM PMOWN.TN_PM_SMLT_RSLT_DTL_REG_EXCL;
SELECT SMLT_STTS,COUNT(*) FROM PMOWN.TN_PM_SMLT_USER_MSTR_V2 GROUP BY SMLT_STTS;
SELECT OWNER_USER_ID,EXCN_YMD,TMNL_ID,AREA_CD,OLD_SMLT_ID FROM PMOWN.TN_PM_SMLT_LEGACY_COND_MAP WHERE SELECTED_YN='Y';
